            BitSet resultSet = new BitSet();
            for (int bitIndex = rootSet.nextSetBit(0); bitIndex >= 0; bitIndex = rootSet.nextSetBit(bitIndex + 1)) {
                if (target.contains(originList.get(bitIndex))) {
